import Foundation
import Testing
@testable import SwiftJXLCore

struct U32DistributionBoundaryTests {
    // Independent §C.2.4 expected bytes: two LSB-first selector bits followed
    // by the chosen payload width. These are not generated by the reader.
    @Test(arguments: [UInt32(0), 1, 255, 256, 65536, 0x12345678, .max])
    func animationDurationExpectedBytes(_ value: UInt32) throws {
        let expected: [UInt32: [UInt8]] = [
            0: [0x00], 1: [0x01], 255: [0xfe, 0x03],
            256: [0x03, 0x04, 0, 0, 0], 65536: [0x03, 0, 0x04, 0, 0],
            0x12345678: [0xe3, 0x59, 0xd1, 0x48, 0],
            .max: [0xff, 0xff, 0xff, 0xff, 0x03]]
        let bytes = try #require(expected[value])
        let distributions: (UInt32Distribution, UInt32Distribution, UInt32Distribution, UInt32Distribution) =
            (.literal(0), .literal(1), .bits(8), .bits(32))
        var writer = BitWriter()
        try writer.writeU32(value, distributions: distributions)
        #expect(writer.bitCount == (value <= 1 ? 2 : value <= 255 ? 10 : 34))
        #expect(writer.finishToData() == Data(bytes))
        var reader = BitReader(Data(bytes))
        #expect(try reader.readU32(distributions) == value)
        var frameWriter = BitWriter()
        try AnimationFrame(duration: value).write(to: &frameWriter, haveAnimation: true, haveTimecodes: false)
        #expect(frameWriter.finishToData() == Data(bytes))
    }

    @Test func narrowerRangesAndOffsets() throws {
        #expect(UInt32Distribution.literal(7).encode(7) == 0)
        #expect(UInt32Distribution.literal(7).encode(8) == nil)
        #expect(UInt32Distribution.bits(1).encode(1) == 1)
        #expect(UInt32Distribution.bits(1).encode(2) == nil)
        #expect(UInt32Distribution.bits(31).encode(0x7fffffff) == 0x7fffffff)
        #expect(UInt32Distribution.bits(31).encode(0x80000000) == nil)
        #expect(UInt32Distribution.bits(32).encode(.max) == UInt32.max)
        #expect(UInt32Distribution.offset(constant: 10, extraBits: 3).encode(9) == nil)
        #expect(UInt32Distribution.offset(constant: 10, extraBits: 3).encode(17) == 7)
        #expect(UInt32Distribution.offset(constant: 10, extraBits: 3).encode(18) == nil)
        #expect(UInt32Distribution.offset(constant: 10, extraBits: 32).encode(.max) == UInt32.max - 10)
        #expect(UInt32Distribution.offset(constant: .max, extraBits: 32).encode(.max) == 0)
        let distributions: (UInt32Distribution, UInt32Distribution, UInt32Distribution, UInt32Distribution) =
            (.literal(5), .offset(constant: 10, extraBits: 3), .bits(4), .bits(32))
        let expected: [(UInt32, [UInt8])] = [(5, [0]), (9, [0x26]), (10, [1]), (17, [0x1d]), (18, [0x4b, 0, 0, 0, 0])]
        for (value, bytes) in expected {
            var writer = BitWriter()
            try writer.writeU32(value, distributions: distributions)
            #expect(writer.finishToData() == Data(bytes))
        }
        var noMatch = BitWriter()
        #expect(throws: BitstreamError.self) {
            try noMatch.writeU32(4, distributions: (.literal(0), .literal(1), .literal(2), .literal(3)))
        }
        #expect(noMatch.bitCount == 0)
    }
}
